def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    doc = app.activeDocument
    print("doc:", doc.name)
    prods = doc.products
    for i in range(prods.count):
        print("product:", prods.item(i).productType)
    cam = adsk.cam.CAM.cast(prods.itemByProductType("CAMProductType"))
    print("cam:", cam)
    if cam:
        for s in cam.setups:
            print("setup:", s.name, s.operationType, "ops:", s.operations.count)
            for m in s.models:
                print("  model:", m.name)
        print("machine:", cam.designData if False else "")
    des = adsk.fusion.Design.cast(prods.itemByProductType("DesignProductType"))
    root = des.rootComponent
    for b in root.bRepBodies:
        print("body:", b.name, b.boundingBox.minPoint.asArray(), b.boundingBox.maxPoint.asArray())
    for o in root.occurrences:
        print("occ:", o.name)
        for b in o.bRepBodies:
            print("   body:", b.name, b.boundingBox.minPoint.asArray(), b.boundingBox.maxPoint.asArray())
    return "ok"

