def run(_context):
    import adsk.core, adsk.cam
    app = adsk.core.Application.get()
    cam = adsk.cam.CAM.cast(app.activeDocument.products.itemByProductType("CAMProductType"))
    s = cam.setups.item(0)
    out = []
    for i in range(s.operations.count):
        o = s.operations.item(i)
        out.append("OP %d %s strategy=%s" % (i, o.name, o.strategy))
        for n in ("tool_spindleSpeed","tool_feedCutting","tool_feedPlunge","tool_coolant",
                  "retractHeight_offset","retractHeight_value","clearanceHeight_value",
                  "topHeight_mode","topHeight_offset","topHeight_value",
                  "bottomHeight_mode","bottomHeight_offset","bottomHeight_value","stepover"):
            try:
                p = o.parameters.itemByName(n)
                out.append("   %s = %s | %s" % (n, p.expression, p.value.value))
            except Exception as e:
                out.append("   %s MISSING" % n)
    return "\n".join(out)
